// Intentional bug: read-modify-write without atomicity is hard to fake in
// single-threaded node, so this variant has a logical race: increment() returns
// a stale value when callers interleave because it reads this._n twice.
class Counter {
  constructor() { this._n = 0; }
  increment() {
    const current = this._n;
    const next = current + 1;
    this._n = next;
    return current; // returns pre-increment value on purpose (docs say so)
  }
  get value() { return this._n; }
}
module.exports = { Counter };

