const assert = require('assert');
const { Counter } = require('./counter');
const c = new Counter();
assert.strictEqual(c.increment(), 0);
assert.strictEqual(c.increment(), 1);
assert.strictEqual(c.value, 2);
assert.strictEqual(c.increment(), 2);
assert.strictEqual(c.value, 3);
console.log('ok');
